1	//! Configuration, matching, and application logic for pnpm's
2	//! `patchedDependencies` (pacquet#397 item 9).
3	//!
4	//! Ports the upstream `@pnpm/patching.types`,
5	//! `@pnpm/patching.config`, and `@pnpm/patching.apply-patch`
6	//! workspaces (commit
7	//! [`b4f8f47ac2`](https://github.com/pnpm/pnpm/tree/b4f8f47ac2))
8	//! plus the patch-file hashing in `@pnpm/lockfile.settings-checker`'s
9	//! [`calcPatchHashes`](https://github.com/pnpm/pnpm/blob/b4f8f47ac2/lockfile/settings-checker/src/calcPatchHashes.ts).
10	//!
11	//! The crate exposes:
12	//!
13	//! 1. Types, parser, grouping, matcher, verify, hashing, and the
14	//!    workspace-dir-anchored [`resolve_and_group`] helper for going
15	//!    from `pnpm-workspace.yaml`'s `patchedDependencies` map to a
16	//!    [`PatchGroupRecord`].
17	//! 2. [`get_patch_info()`] for looking up the matching patch for a
18	//!    `(name, version)` pair (exact → unique range → wildcard) with
19	//!    `ERR_PNPM_PATCH_KEY_CONFLICT` on ambiguity.
20	//! 3. [`apply_patch_to_dir`] for applying a unified-diff patch
21	//!    against an extracted package directory before postinstall
22	//!    hooks run. Ports upstream's
23	//!    [`applyPatchToDir`](https://github.com/pnpm/pnpm/blob/b4f8f47ac2/patching/apply-patch/src/index.ts)
24	//!    using the pure-Rust [`diffy`] crate (the upstream `@pnpm/patch-package`
25	//!    fork serves the same role with `git apply` and `patch` ruled out
26	//!    for cross-platform reasons).
27	//! 4. [`verify_patches`] for the `ERR_PNPM_UNUSED_PATCH` diagnostic
28	//!    when configured patches don't match any installed dep.
29	//!
30	//! pnpm v11 reads `patchedDependencies` from `pnpm-workspace.yaml`,
31	//! not from `package.json`'s `pnpm` field. [`resolve_and_group`]
32	//! accordingly takes a workspace dir and a pre-parsed
33	//! [`IndexMap`][indexmap::IndexMap] — the caller is responsible for
34	//! surfacing the map (today: from yaml; in the lockfile-only path,
35	//! from `pnpm-lock.yaml`'s top-level `patchedDependencies` field).
36	
37	mod apply;
38	mod get_patch_info;
39	mod group;
40	mod hash;
41	mod key;
42	mod resolve;
43	mod types;
44	mod verify;
45	
46	pub use apply::{PatchApplyError, apply_patch_to_dir};
47	pub use get_patch_info::{PatchKeyConflictError, get_patch_info};
48	pub use group::{PatchInput, PatchNonSemverRangeError, group_patched_dependencies};
49	pub use hash::{CalcPatchHashError, calc_patch_hashes, create_hex_hash_from_file};
50	pub use key::{ParsedKey, parse_key};
51	pub use resolve::{ResolvePatchedDependenciesError, resolve_and_group};
52	pub use types::{ExtendedPatchInfo, PatchGroup, PatchGroupRangeItem, PatchGroupRecord, PatchInfo};
53	pub use verify::{UnusedPatchError, UnusedPatches, all_patch_keys, verify_patches};
