/// Fold the matching `patchedDependencies` entry (if any) into a
/// package's id, returning `pkgIdWithPatchHash`.
///
/// Looks the resolved `name@version` up in
/// [`TreeCtx::patched_dependencies`] via
/// [`get_patch_info`](pacquet_patching::get_patch_info) (exact →
/// unique range → wildcard). On a match, appends `(patch_hash=<hash>)`
/// to `base_id` and records the configured key (the exact key
/// `foo@1.0.0` or the range key `foo@^1.0.0`) in
/// [`TreeCtx::applied_patches`]. Returns `base_id` unchanged when
/// patching is disabled, the package has no `name@version` (git /
/// tarball / local resolvers), or nothing matches. Surfaces
/// [`ResolveDependencyTreeError::PatchKeyConflict`] when two or more
/// range entries both satisfy the version.
async fn apply_patch_to_id(
    ctx: &TreeCtx,
    result: &pacquet_resolving_resolver_base::ResolveResult,
    base_id: String,
) -> Result<String, ResolveDependencyTreeError> {
    let Some(groups) = ctx.patched_dependencies.as_deref() else {
        return Ok(base_id);
    };
    let Some(name_ver) = result.name_ver.as_ref() else {
        return Ok(base_id);
    };
    let name = name_ver.name.to_string();
    let version = name_ver.suffix.to_string();
    let patch = get_patch_info(Some(groups), &name, &version)
        .map_err(ResolveDependencyTreeError::PatchKeyConflict)?;
    let Some(patch) = patch else {
        return Ok(base_id);
    };
    ctx.applied_patches.lock().await.insert(patch.key.clone());
    Ok(format!("{base_id}(patch_hash={})", patch.hash))
}

