7	/// Input to [`group_patched_dependencies`]: the
8	/// `pnpm.patchedDependencies` map after hashes have been computed.
9	///
10	/// One entry per `patchedDependencies` key. Upstream accepts either a
11	/// string hash (the historical shape — see
12	/// [`PatchFile`](https://github.com/pnpm/pnpm/blob/b4f8f47ac2/patching/config/src/groupPatchedDependencies.ts#L23))
13	/// or a `{ hash, patchFilePath }` object. Pacquet collapses both into
14	/// the latter at config-load time, so the grouper only sees the
15	/// resolved shape.
16	#[derive(Debug, Clone)]
17	pub struct PatchInput {
18	    pub hash: String,
19	    pub patch_file_path: Option<std::path::PathBuf>,
20	}
21	
22	/// Raised when a `patchedDependencies` key's version segment is
23	/// non-empty, not a valid semver version, and not a valid semver
24	/// range.
25	///
26	/// Mirrors upstream's
27	/// [`ERR_PNPM_PATCH_NON_SEMVER_RANGE`](https://github.com/pnpm/pnpm/blob/b4f8f47ac2/patching/config/src/groupPatchedDependencies.ts#L30-L31).
28	#[derive(Debug, Display, Error, Diagnostic)]
29	#[display("{non_semver_version} is not a valid semantic version range.")]
30	#[diagnostic(code(ERR_PNPM_PATCH_NON_SEMVER_RANGE))]
31	pub struct PatchNonSemverRangeError {
32	    pub non_semver_version: String,
33	}
34	
35	/// Bucketize `patchedDependencies` by package name and match flavor.
36	///
37	/// Ports upstream's
38	/// [`groupPatchedDependencies`](https://github.com/pnpm/pnpm/blob/b4f8f47ac2/patching/config/src/groupPatchedDependencies.ts#L6-L49).
39	/// For each entry:
40	///
41	/// 1. Parse the key.
42	/// 2. `name@<exact-semver>` → `group.exact[version]`.
43	/// 3. `name@<range>` with `range.trim() == "*"` → `group.all`.
44	/// 4. `name@<range>` otherwise → push onto `group.range`.
45	/// 5. Bare `name` (or unparsable key) → `group.all`.
46	///
47	/// Rule 2/3/4 order mirrors upstream. Note rule 5's wildcard wins
48	/// over a later explicit `name@*`: upstream uses the bare-name branch
49	/// last, so a bare `name` key overwrites whatever the `*` branch set.
50	/// Pacquet matches that behavior.
51	pub fn group_patched_dependencies<Iter>(
52	    entries: Iter,
53	) -> Result<PatchGroupRecord, PatchNonSemverRangeError>
54	where
55	    Iter: IntoIterator<Item = (String, PatchInput)>,
56	{
57	    let mut result: PatchGroupRecord = PatchGroupRecord::new();
58	
59	    for (key, info) in entries {
60	        let parsed = parse_key(&key);
61	        let extended = ExtendedPatchInfo {
62	            hash: info.hash,
63	            patch_file_path: info.patch_file_path,
64	            key: key.clone(),
65	        };
66	
67	        match (parsed.name, parsed.version, parsed.non_semver_version) {
68	            (Some(name), Some(version), _) => {
69	                let group = result.entry(name.to_string()).or_default();
70	                group.exact.insert(version.to_string(), extended);
71	            }
72	            (Some(name), None, Some(non_semver_version)) => {
73	                if Range::parse(non_semver_version).is_err() {
74	                    return Err(PatchNonSemverRangeError {
75	                        non_semver_version: non_semver_version.to_string(),
76	                    });
77	                }
78	                let group = result.entry(name.to_string()).or_default();
79	                if non_semver_version.trim() == "*" {
80	                    group.all = Some(extended);
81	                } else {
82	                    group.range.push(PatchGroupRangeItem {
83	                        version: non_semver_version.to_string(),
84	                        patch: extended,
85	                    });
86	                }
87	            }
88	            _ => {
89	                // Bare name (or unparsable): wildcard for the package
90	                // matching the whole key verbatim.
91	                let group = result.entry(key.clone()).or_default();
92	                group.all = Some(extended);
93	            }
94	        }
95	    }
96	
97	    Ok(result)
98	}
